  List<int> evens = [];
  List<int> odds = [];

  for (int i = 0; i < l.length; i++) {
    if (i % 2 == 0) {
      evens.add(l[i]);
    } else {
      odds.add(l[i]);
    }
  }

  evens.sort();

  List<int> ans = [];
  for (int i = 0; i < odds.length; i++) {
    ans.add(evens[i]);
    ans.add(odds[i]);
  }

  if (evens.length > odds.length) {
    ans.add(evens[evens.length - 1]);
  }

  return ans;
}

