  List<String> words = s.split(' ');

  for (String word in words) {
    if (word.isEmpty) continue;

    int nConsonants = 0;
    for (int i = 0; i < word.length; i++) {
      String char = word[i].toLowerCase();
      if (char != 'a' && char != 'e' && char != 'i' && char != 'o' && char != 'u') {
        nConsonants++;
      }
    }

    if (nConsonants == n) {
      result.add(word);
    }
  }

  return result;
}

