int fn0(int n) {
  int product = 1;
  int oddCount = 0;
  for (var digit in n.toString().split('')) {
    int intDigit = int.parse(digit);
    if (intDigit % 2 == 1) {
      product = product * intDigit;
      oddCount++;
    }
  }
  if (oddCount == 0) {
    return 0;
  } else {
    return product;
  }
}

