import 'dart:math';
@pragma('vm:entry-point')


num fn0(List<String> operator, List<int> operand) {
  List<num> values = List<num>.from(operand);
  List<String> ops = List<String>.from(operator);

  // Handle exponentiation first (highest precedence)
  int i = 0;
  while (i < ops.length) {
    if (ops[i] == '**') {
      values[i] = pow(values[i], values[i + 1]);
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  // Handle multiplication and floor division (medium precedence)
  i = 0;
  while (i < ops.length) {
    if (ops[i] == '*') {
      values[i] = values[i] * values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else if (ops[i] == '//') {
      values[i] = (values[i] ~/ values[i + 1]).toInt();
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  // Handle addition and subtraction (lowest precedence)
  i = 0;
  while (i < ops.length) {
    if (ops[i] == '+') {
      values[i] = values[i] + values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else if (ops[i] == '-') {
      values[i] = values[i] - values[i + 1];
      values.removeAt(i + 1);
      ops.removeAt(i);
    } else {
      i++;
    }
  }

  return values[0];
}

