List<int> fn0(int a, int b) {
  int lower = max(2, min(a, b));
  int upper = min(8, max(a, b));

  List<int> result = [];
  for (int i = lower; i <= upper; i++) {
    if (i % 2 == 0) {
      result.add(i);
    }
  }
  return result;
}

